/* ---------- History: every entry, newest first. Tap one to change or remove it. ---------- */
function entryRow(e){ return `<li><button type="button" class="tlr" data-act="entry" data-v="${e.id}"><span class="tt">${e.k==='none'?'':hm(e.t)}</span><span class="tx">${e.k==='meal'?mealText(e):e.k==='fx'?`<span class="fxm" aria-hidden="true"></span>${esc(fxName(e.c))}${e.c==='sleep'?`<small>${L('counted with the night before','compté avec la nuit d’avant')}</small>`:''}`:`<span class="muted">${L('No effects reported','Aucun effet noté')}</span>`}</span></button></li>`; }
function vHist(){ const I=IX(), by={}; for(const e of S.ev){ const k=e.k==='none'?e.d:E.dayKey(e.t,S.roll); (by[k]||(by[k]=[])).push(e); }
  const keys=Object.keys(by).sort().reverse(), N=UI.histN||30, T=today();
  /* a day that was missed: a meal or an effect can be added to any day up to today */
  const addDay=`<div class="card" style="padding:10px 14px"><div class="row"><label class="small" for="hDay">${L('Add to a day','Ajouter à une journée')}</label><input type="date" id="hDay" class="sel" style="min-height:44px" data-in="hday" value="${esc(UI.hday||kAdd(T,-1))}" max="${T}"></div><div class="row" style="margin-top:8px"><button type="button" class="btn ghost sm" data-act="hmeal">+ ${L('Meal','Repas')}</button><button type="button" class="btn ghost sm" data-act="hfx">+ ${L('Effect','Effet')}</button></div></div>`;
  if(!keys.length) return `<div class="eyebrow">${L('History','Historique')}</div>${addDay}<p class="muted">${L('Nothing reported yet.','Rien de noté pour l’instant.')}</p>`;
  return `<div class="eyebrow">${L('History','Historique')}</div>${addDay}<p class="small muted">${L('Tap an entry to change or remove it.','Appuie sur une entrée pour la modifier ou la retirer.')}</p>`
    +keys.slice(0,N).map(k=>{ const d=I.D[k], open=d&&d.meals.length&&!d.closed, st=!d||!d.meals.length?L('no meal','aucun repas'):d.closed?L('complete','complète'):L('not complete','pas complète');
      return `<h3 style="margin:18px 0 0;font-size:1rem">${esc(dLabel(k))} <span class="muted" style="font-weight:400;font-family:system-ui,sans-serif;font-size:.85rem">· ${st}</span></h3>${open?`<button type="button" class="lnk" data-act="none" data-v="${k}">${L('No effects that day','Aucun effet ce jour-là')}</button>`:''}<ul class="tl">${by[k].slice().sort((a,b)=>b.t-a.t).map(entryRow).join('')}</ul>`; }).join('')
    +(keys.length>N?`<div class="row" style="margin-top:12px"><button type="button" class="btn ghost sm" data-act="histmore">${L('Show older days','Montrer les jours plus anciens')}</button></div>`:''); }
/* the amounts of one meal, as a line of text. plain = ordinary spaces, for text that gets copied */
function amountsLine(am,plain){ const u=(x,un,d)=>plain?num(x,d).replace(/[\u00a0\u202f]/g,' ')+' '+un:U(x,un,d), P=[L('fat','gras')+' '+u(am.fat,'g'),L('protein','protéines')+' '+u(am.prot,'g')];
  if(am.cplx>0||am.sug>0||!(am.unk>0)) P.push(L('complex carbs','glucides complexes')+' '+u(am.cplx,'g'),L('sugars','sucres')+' '+u(am.sug,'g')+(am.lact>=0.05?' ('+L('lactose','lactose')+' '+u(am.lact,'g')+')':''));
  if(am.unk>0) P.push(L('carbs, kind not listed','glucides, sorte non indiquée')+' '+u(am.unk,'g'));
  P.push(L('fibre','fibres')+' '+u(am.fib,'g')); if(am.alc>0) P.push(L('alcohol','alcool')+' '+u(am.alc,'g'));
  if(am.histN>0) P.push(L('histamine est.','histamine est.')+' '+u(am.hist,'mg',am.hist<1?2:1)+(am.histUnk>0?L(' plus a food with no figure',' plus un aliment sans chiffre'):''));
  P.push(u(am.kcal,'kcal',0)); if(am.noNum>0) P.push(L('a food with no numbers is not counted','un aliment sans chiffres n’est pas compté'));
  return P.join(plain?', ':' · '); }
/* what one meal held, of the things the Threshold rows count: only what is there, each with its amount */
function heldLine(am){ const P=[]; for(const f of E.FAMS) for(const k of f[1]) if(held(am,k)&&E.usable(am,k)) P.push(L(BARN[k][0],BARN[k][1]).toLowerCase()+' '+amtTxt(k,am[k]||0)); return P.join(' · '); }
function entrySheet(keep){ const e=S.ev.find(x=>x.id===UI.en.id); if(!e){ closeSheet(); return; } const k=e.k==='none'?e.d:E.dayKey(e.t,S.roll), rm=`<button type="button" class="btn ghost sm" data-act="del" data-v="${e.id}">${L('Remove','Retirer')}</button>`;
  if(e.k==='meal') showSheet(`<h3 id="sheetTitle">${L('Meal','Repas')} · ${esc(dLabel(k))}, ${hm(e.t)}</h3>
    <ul class="evs">${e.items.map(it=>{ const f=food(it.key); return `<li>${qtxt(it.q)}\u00a0×\u00a0<button type="button" class="lnk" data-act="foodrd" data-v="${esc(it.key)}">${esc(fname(f))}</button>${fserv(f)?` <span class="small muted">${esc(fserv(f))}</span>`:''}</li>`; }).join('')}</ul>
    <p class="small">${amountsLine(E.mealAmounts(e,food))}</p><div class="row"><button type="button" class="btn sm" data-act="mealedit" data-v="${e.id}">${L('Change','Modifier')}</button>${rm}</div>`,keep);
  else if(e.k==='fx'){ const h=winFor(e.c), W=h*E.H, sleep=e.c==='sleep', dk=E.fxDay(e,S.roll), meals=S.ev.filter(x=>x.k==='meal'&&x.t<=e.t);
    /* the meals the lists set this effect beside: within the slider's hours before it. Poor sleep is counted with the day before, so it shows that day's meals. */
    const bef=sleep?meals.filter(x=>E.dayKey(x.t,S.roll)===dk):meals.filter(x=>x.t>=e.t-W).reverse(), out=sleep?[]:meals.filter(x=>x.t<e.t-W&&E.dayKey(x.t,S.roll)===k);
    const row=x=>`<li><button type="button" class="lnk" data-act="entry" data-v="${x.id}">${hm(x.t)}</button>${sleep?'':' · '+gapTxt(e.t-x.t)}<br>${mealText(x)}${(h=>h?`<br><span class="small muted held">${h}</span>`:'')(heldLine(E.mealAmounts(x,food)))}</li>`;
    const outs=out.map(x=>hm(x.t)), outL=outs.length>1?outs.slice(0,-1).join(', ')+L(' and ',' et ')+outs[outs.length-1]:outs[0];
    showSheet(`<h3 id="sheetTitle">${esc(fxName(e.c))}</h3><p class="small muted" style="margin:-4px 0 12px">${esc(dLabel(k))}, ${hm(e.t)}</p>
    <p style="margin:0"><b id="befHead">${sleep?L('Counted with the day before','Compté avec la journée d’avant')+COL()+esc(dLabel(dk)):h===1?L('In the hour before','Dans l’heure d’avant'):L(`In the ${h} hours before`,`Dans les ${h} heures d’avant`)}</b></p>
    ${bef.length?`<ul class="evs" id="befList">${bef.map(row).join('')}</ul>`:`<p class="small muted" id="befNone" style="margin:4px 0 0">${sleep?L('No meal reported that day.','Aucun repas noté ce jour-là.'):L('No meal reported in them.','Aucun repas noté pendant ces heures.')}</p>`}
    ${sleep?'':`<p class="small muted" id="befNote" style="margin:8px 0 0">${L('The hours are the ones set on the slider in Threshold.','Les heures sont celles réglées sur le curseur de l’onglet Seuil.')}${out.length?' '+(out.length>1?L(`Meals at ${outL} are outside them.`,`Des repas à ${outL} sont en dehors.`):L(`A meal at ${outL} is outside them.`,`Un repas à ${outL} est en dehors.`)):''}</p>`}
    <p style="margin:12px 0 0"><button type="button" class="lnk" data-act="fxthr" data-v="${esc(e.c)}">${L(`${esc(fxName(e.c))} in Threshold`,`${esc(fxName(e.c))} dans l’onglet Seuil`)}</button></p>
    <div class="row" style="margin-top:14px"><label class="small" for="enAt">${L('Time','Heure')}</label><input type="time" id="enAt" class="sel tm" data-in="enat" value="${esc(UI.en.at)}"><button type="button" class="btn sm" data-act="ensave">${L('Save the time','Enregistrer l’heure')}</button></div><div class="row" style="margin-top:12px">${rm}</div><p class="mine">${MINE()}</p>`,keep); }
  else showSheet(`<h3 id="sheetTitle">${L('No effects reported','Aucun effet noté')}</h3><p class="small muted">${esc(dLabel(k))}</p><div class="row">${rm}</div>`,keep); }

/* ---------- Ask AI: the log as text, copied. The app writes no question, and sends nothing. ---------- */
/* the other compounds one meal held, for the copied text: caffeine and the rest, each with its amount */
function compLine(am){ return E.COMPS.filter(k=>E.NUTR.indexOf(k)<0&&held(am,k)).map(k=>L(BARN[k][0],BARN[k][1]).toLowerCase()+' '+amtTxt(k,am[k]||0)).join(', '); }
function aiText(scope){ const T=today(), from=scope==='month'?kAdd(T,-29):null, dk=e=>e.k==='none'?e.d:E.dayKey(e.t,S.roll), ev=S.ev.filter(e=>!from||dk(e)>=from);
  const I=E.index({ev,roll:S.roll,twin:winH()},food,now()), O=[], pl=s=>String(s).replace(/[\u00a0\u202f]/g,' '), rd=E.reportedDays(I), withMeal=I.keys.filter(k=>I.D[k].meals.length).length;
  O.push(L('My own log from Threshold Log. Not medical advice.','Mon propre journal du Threshold Log. Pas un avis médical.'));
  O.push(L(`Made ${T} with Threshold Log ${VER}. Entries from ${I.keys[0]||T} to ${I.keys[I.keys.length-1]||T}.`,`Fait le ${T} avec Threshold Log ${VER}. Entrées du ${I.keys[0]||T} au ${I.keys[I.keys.length-1]||T}.`));
  O.push(L(`Days with a meal: ${withMeal}. Complete days: ${rd}. A day is complete when it has a meal and either an effect or a tap on "No effects today". Only complete days are in the tallies.`,`Jours avec un repas\u00a0: ${withMeal}. Journées complètes\u00a0: ${rd}. Une journée est complète quand elle a un repas et soit un effet, soit un appui sur «\u00a0Aucun effet aujourd’hui\u00a0». Seules les journées complètes sont dans les comptes.`));
  O.push(L('Amounts per serving are from Health Canada’s Canadian Nutrient File (2015). Histamine is an estimate: the weight of a serving times the average for its food type in a 2011 table from the European Food Safety Authority. It is not a measurement.','Les quantités par portion viennent du Fichier canadien sur les éléments nutritifs de Santé Canada (2015). L’histamine est une estimation\u00a0: le poids d’une portion multiplié par la moyenne de son type d’aliment dans un tableau de 2011 de l’Autorité européenne de sécurité des aliments. Ce n’est pas une mesure.'));
  if(S.roll) O.push(L(`My day starts at ${S.roll}:00.`,`Ma journée commence à ${S.roll} h.`));
  if(S.list.length) O.push(L('My list (the foods I eat as a rule): ','Ma liste (les aliments que je mange d’habitude)\u00a0: ')+S.list.map(k=>fname(food(k))).join('; ')+'.');
  if(S.imp&&S.imp.out.length) O.push(L('Rejected in my Food Trial Log: ','Rejetés dans mon Food Trial Log\u00a0: ')+S.imp.out.map(r=>`${fname(food(r.key))} (${r.d}, ${pl(whyTxt(r)).replace(/ · /g,', ')})`).join('; ')+'.');
  const cs=Object.entries(S.concl).filter(([k,v])=>v&&v.trim()); if(cs.length) O.push(L('My conclusions, in my own words: ','Mes conclusions, dans mes mots\u00a0: ')+cs.map(([k,v])=>(k.startsWith('food:')?fname(food(k.slice(5))):BARN[k]?L(BARN[k][0],BARN[k][1]):k)+COL()+L('"','«\u00a0')+v.trim()+L('"','\u00a0»')).join('; ')+'.');
  for(const mode of ['meal','day']){ O.push('',mode==='meal'?L(`TALLIES AFTER A MEAL (the amount in one meal; effects reported in ${hrsAfter(winH())}: my own setting, from 1 to 8 hours)`,`COMPTES APRÈS UN REPAS (la quantité dans un repas; effets notés dans ${hrsAfter(winH())} : mon propre réglage, de 1 à 8 heures)`):L('TALLIES OVER A DAY (the total for a day; effects reported that day, that night and the next day)','COMPTES SUR UNE JOURNÉE (le total d’une journée; effets notés ce jour-là, cette nuit-là et le lendemain)'));
    const had=new Set(E.rows(I,mode).filter(r=>r.any).map(r=>r.b));   /* the first rows always; another compound when a counted meal held some of it */
    for(const b of E.BUCKETS.concat(['alc','caf'],E.COMPS.filter(k=>k!=='caf'&&had.has(k)))){ const B=E.bar(I,b,mode); O.push(L(BARN[b][0],BARN[b][1])+', '+(BARN[b][2]==='p'?'portions':BARN[b][2])); if(!B.n){ O.push('  '+L('nothing counted yet','rien de compté pour l’instant')); continue; }
      for(const s of [B.zero].concat(B.steps)){ if(!s.n) continue; const fx=Object.entries(s.fx).sort((a,c)=>c[1]-a[1]).map(([c,n])=>fxLow(c)+' '+n).join(', '); O.push('  '+pl(stepRange(B,s))+COL()+pl(stepCount(B,s))+(fx?' ('+fx+')':'')); }
      if(B.left) O.push('  '+L(`left out: ${B.left} (${leftWhy2(b)})`,`laissés de côté\u00a0: ${B.left} (${leftWhy2(b)})`)); } }
  /* the marks the Threshold tab shows, for any effect and for each effect reported: the app's own sentences, and the rows with none */
  const codes=Array.from(new Set(ev.filter(e=>e.k==='fx').map(e=>e.c)));
  for(const mode of ['meal','day']){ const blocks=[];
    for(const sel of [null].concat(codes.map(c=>[c]))){ const R=E.rows(I,mode,sel).filter(r=>r.any), s0=R.length?R[0].s:null; if(!s0||!s0.nHit||!s0.nRest) continue;
      const mk=E.grouped(R.filter(r=>r.s.at!=null)), no=R.filter(r=>r.s.at==null), T0=E.table(I,mode,sel)[0].rows[0], nH=T0.hit.n, nA=T0.hit.n+T0.rest.n;
      blocks.push(cap(sel?fxLow(sel[0]):L('any effect','tout effet'))+L(`, ${nH} of ${nA} ${unitWord(mode,nA)}`,`, ${nH} sur ${nA} ${unitWord(mode,nA)}`)+COL());
      for(const r of mk) blocks.push('  '+L(BARN[r.b][0],BARN[r.b][1])+COL()+markTxt(r.b,r.s));
      const k=no.length; if(k) blocks.push('  '+(mk.length?L(k===1?'No mark on the other row.':`No mark on the other ${k} rows.`,k===1?'Aucune marque sur l’autre ligne.':`Aucune marque sur les ${k} autres lignes.`):L('No row has a mark.','Aucune ligne n’a de marque.'))); }
    if(blocks.length){ O.push('',mode==='meal'?L('MARKS AFTER A MEAL','MARQUES APRÈS UN REPAS'):L('MARKS OVER A DAY','MARQUES SUR UNE JOURNÉE'));
      if(mode==='meal') O.push(L('A mark is the amount that best puts the meals or days with the effect on one side of it and the others on the other side. "With" and "without" are with and without the effect. A row has no mark when no amount does better than none.','Une marque est la quantité qui met le mieux les repas ou les journées avec l’effet d’un côté et les autres de l’autre. «\u00a0Avec\u00a0» et «\u00a0sans\u00a0» veulent dire avec et sans l’effet. Une ligne n’a pas de marque quand aucune quantité ne sépare ses points.'));
      for(const l of blocks) O.push(l.replace(/[\u00a0\u202f](?!:)/g,' ').replace(/\s+$/,'')); } }   /* plain spaces in the amounts, as in the rest of the text; the space before a colon stays */
  O.push('',L('ENTRIES','ENTRÉES'));
  for(const k of I.keys.slice().reverse()){ const d=I.D[k], [y,m,da]=k.split('-').map(Number), wd=new Date(y,m-1,da).toLocaleDateString(LOC(),{weekday:'long'});
    O.push(`${k}, ${wd}, ${!d.meals.length?L('no meal','aucun repas'):d.closed?L('complete','complète'):L('not complete','pas complète')}`);
    const rows=d.meals.map(m=>[m.e.t,`  ${hm(m.e.t)} ${L('meal','repas')}${COL()}${m.e.items.map(it=>{ const f=food(it.key); return pl(qtxt(it.q))+' x '+fname(f)+(fserv(f)?' ('+fserv(f)+')':''); }).join('; ')}. ${cap(amountsLine(m.am,true))}${(c=>c?'. '+L('Compounds','Composés')+COL()+pl(c):'')(compLine(m.am))}`]).concat(d.rep.map(e=>[e.t,`  ${hm(e.t)} ${L('effect','effet')}${COL()}${fxLow(e.c)}`])).sort((a,b)=>a[0]-b[0]);
    for(const r of rows) O.push(r[1]); if(d.none) O.push('  '+L('no effects reported that day','aucun effet noté ce jour-là')); }
  return O.join('\n'); }
function aiSheet(keep){ const u=UI.ai; u.text=aiText(u.scope);
  showSheet(`<h3 id="sheetTitle">${L('Ask AI','Demander à l’IA')}</h3>
  <p class="small">${L('This copies your log as text: the tallies and the marks behind the Threshold rows, your meals with what they held, and your effects with their times. Paste it into the AI you use and ask your own question. The app writes no question.','Ça copie ton journal en texte\u00a0: les comptes et les marques derrière les lignes de Seuil, tes repas avec ce qu’ils contenaient, et tes effets avec leurs heures. Colle-le dans l’IA que tu utilises et pose ta propre question. L’app n’écrit aucune question.')}</p>
  <p class="small"><b>${L('Once you paste it somewhere, it has left your phone.','Une fois que tu le colles quelque part, il a quitté ton téléphone.')}</b></p>
  <div class="gtabs seg" role="group" aria-label="${L('How much','Quelle part')}"><button type="button" data-act="aiscope" data-v="month" aria-pressed="${u.scope==='month'}">${L('This month','Ce mois-ci')}</button><button type="button" data-act="aiscope" data-v="all" aria-pressed="${u.scope==='all'}">${L('Everything','Tout')}</button></div>
  <div class="row"><button type="button" class="btn primary sm" data-act="aicopy">${L('Copy','Copier')}</button><span class="small muted">${L(`${u.text.length.toLocaleString('en-CA')} characters`,`${u.text.length.toLocaleString('fr-CA')} caractères`)}</span></div>
  <textarea class="out" readonly aria-label="${L('The text that gets copied','Le texte qui est copié')}" style="min-height:220px;margin-top:10px">${esc(u.text)}</textarea>`,keep); }

/* ---------- a food from its label ---------- */
const usedIn=id=>S.ev.filter(e=>e.k==='meal'&&e.items.some(it=>it.key==='L'+id)).length;
function labelSheet(keep){ const u=UI.lb, n=u.id?usedIn(u.id):0;
  const inp=(k,l,ph,dec)=>`<label class="lbf"><span>${l}</span><input class="sel" data-in="lb" data-k="${k}" value="${esc(u[k]==null?'':u[k])}" ${dec?'inputmode="decimal"':''} placeholder="${ph||''}" autocomplete="off" maxlength="${dec?8:60}"></label>`;
  showSheet(`<h3 id="sheetTitle">${u.id?L('Change this food','Modifier cet aliment'):L('Add a food from its label','Ajouter un aliment selon son étiquette')}</h3>
  <p class="small">${L('Copy the numbers for one serving from the Nutrition Facts table.','Copie les chiffres d’une portion à partir du tableau de la valeur nutritive.')}</p>
  <div class="lbg">${inp('n',L('Name','Nom'),'')}${inp('s',L('Serving','Portion'),L('1 bar (40 g)','1 barre (40 g)'))}</div>
  <div class="lbg two">${inp('kcal',L('Calories','Calories'),'',1)}${inp('fat',L('Fat, g','Lipides, g'),'',1)}${inp('carb',L('Carbohydrate, g','Glucides, g'),'',1)}${inp('fib',L('Fibre, g','Fibres, g'),'',1)}${inp('sug',L('Sugars, g','Sucres, g'),'',1)}${inp('prot',L('Protein, g','Protéines, g'),'',1)}${inp('lact',L('Lactose, g','Lactose, g'),'',1)}</div>
  <p class="small muted">${L('A label doesn’t list lactose: leave it empty unless you know it. With Sugars left empty, the carbs count as “kind not listed”.','Une étiquette n’indique pas le lactose\u00a0: laisse la case vide à moins de le savoir. Si Sucres reste vide, les glucides comptent comme «\u00a0sorte non indiquée\u00a0».')}</p>
  <div class="chips pickn" style="margin:8px 0"><button type="button" class="chip" data-act="lbh" aria-pressed="${!!u.h}"><span>${L('It is a histamine food','C’est un aliment à histamine')}<br><span class="muted small">${L('Aged, fermented, cured or canned. It has no figure, so its meals stay out of the histamine bar.','Vieilli, fermenté, salé-séché ou en conserve. Il n’a pas de chiffre, alors ses repas restent hors de la barre d’histamine.')}</span></span></button></div>
  <p class="small" style="margin:10px 0 0"><b>${L('Its ingredient list names','Sa liste d’ingrédients nomme')}</b></p>
  <div class="chips pickn" style="margin:6px 0 4px">${[['flav','A flavour','Un arôme'],['swt','A sweetener','Un édulcorant'],['sulph','Sulphites','Des sulfites'],['nitr','Nitrites','Des nitrites']].map(([k,en,fr])=>`<button type="button" class="chip" data-act="lbt" data-k="${k}" aria-pressed="${(u.t||[]).indexOf(k)>=0}">${L(en,fr)}</button>`).join('')}</div>
  <p class="small" style="margin:0 0 10px"><button type="button" class="lnk" data-act="lbflav">${L('What a flavouring can hold','Ce qu’un arôme peut contenir')}</button></p>
  <div class="row"><button type="button" class="btn primary sm" data-act="lbsave">${L('Save','Enregistrer')}</button>${u.id&&!n?`<button type="button" class="btn ghost sm" data-act="lbdel">${L('Remove','Retirer')}</button>`:''}${u.id?`<button type="button" class="btn ghost sm" data-act="label">${L('Add another','En ajouter un autre')}</button>`:''}</div>
  ${u.id&&n?`<p class="small muted">${L(`It is in ${n} reported meal${n>1?'s':''}, so it can be changed and not removed.`,`Il est dans ${n} repas noté${n>1?'s':''}, alors il peut être modifié mais pas retiré.`)}</p>`:''}
  ${S.custom.length&&!u.id?`<h3 style="margin-top:16px">${L('Your label foods','Tes aliments selon l’étiquette')}</h3><ul class="evs">${S.custom.map(c=>`<li><button type="button" class="lnk" data-act="lbedit" data-v="${esc(c.id)}">${esc(c.n)}</button> <span class="small muted">${esc(c.s||'')}</span></li>`).join('')}</ul>`:''}`,keep); }

/* ---------- backup, restore, erase ---------- */
function backupSheet(){ UI.bk=JSON.stringify({app:'threshold-log',ver:VER,saved:new Date().toISOString(),state:S});
  showSheet(`<h3 id="sheetTitle">${L('Back up my data','Sauvegarder mes données')}</h3><p class="small">${L('<b>The backup holds what you reported about your body.</b> Keep it somewhere private. To bring it back, use “Restore from a backup”.','<b>La sauvegarde contient ce que tu as noté sur ton corps.</b> Conserve-la dans un endroit privé. Pour la ramener, utilise «\u00a0Restaurer à partir d’une sauvegarde\u00a0».')}</p>
  <p class="small muted">${S.bkAt?L('Last backup','Dernière sauvegarde')+COL()+esc(dShort(S.bkAt))+'.':L('No backup yet.','Aucune sauvegarde pour l’instant.')} ${L('The website and the installed app can each keep their own data: move between them with a backup.','Le site Web et l’app installée peuvent garder chacun leurs propres données\u00a0: passe de l’un à l’autre à l’aide d’une sauvegarde.')}</p>
  <div class="row"><button type="button" class="btn primary sm" data-act="bkcopy">${L('Copy the backup','Copier la sauvegarde')}</button>${FRAMED?'':`<button type="button" class="btn ghost sm" data-act="bkfile">${L('Download a file','Télécharger un fichier')}</button>`}</div>
  <textarea class="out" readonly aria-label="${L('Backup text','Texte de sauvegarde')}" style="margin-top:10px">${esc(UI.bk)}</textarea>`); }
function restoreSheet(){ showSheet(`<h3 id="sheetTitle">${L('Restore a backup','Restaurer une sauvegarde')}</h3><p class="small">${L('Pick the backup file, or paste the backup text.','Choisis le fichier de sauvegarde ou colle le texte de sauvegarde.')}</p>
  <div class="row" style="margin-bottom:10px"><button type="button" class="btn sm" data-act="pickfile">${L('Choose the file','Choisir le fichier')}</button></div><input type="file" id="restoreFile" accept="application/json,.json" class="vh" tabindex="-1" aria-hidden="true">
  <label class="vh" for="restoreText">${L('Backup text','Texte de sauvegarde')}</label><textarea class="out" id="restoreText" placeholder="${L('…or paste it here','…ou colle-le ici')}" style="min-height:90px"></textarea>
  <div class="row" style="margin-top:10px"><button type="button" class="btn ghost sm" data-act="usetext">${L('Restore from the pasted text','Restaurer à partir du texte collé')}</button></div>`); }
function parseBackup(text){ let o; try{ o=JSON.parse(text); }catch(e){ o=null; }
  if(o&&o.app==='food-trial-log'){ toast(L('That is a Food Trial Log backup. Bring it in from the Nutrition tab.','C’est une sauvegarde du Food Trial Log. Importe-la à partir de l’onglet Nutrition.')); return; }
  if(!o||o.app!=='threshold-log'||!o.state||typeof o.state!=='object'||o.state.v!==1||!Array.isArray(o.state.ev)){ toast(L('That isn’t a Threshold Log backup','Ce n’est pas une sauvegarde du Threshold Log')); return; }
  UI.restore=o; showSheet(`<h3 id="sheetTitle">${L('Restore this backup?','Restaurer cette sauvegarde?')}</h3><p>${L(`It’s from ${esc(dShort(o.saved)||'an unknown date')}. Everything on this phone gets replaced by it.`,`Elle date du ${esc(dShort(o.saved)||'(date inconnue)')}. Tout ce qui est sur ce téléphone sera remplacé par elle.`)}</p><button type="button" class="btn primary sm" data-act="dorestore">${L('Replace everything','Tout remplacer')}</button>`); }
function eraseAll(){ if(STORE==='bad') STORE='ok'; try{ localStorage.removeItem(KEY); }catch(e){} NUTRI.unshare(); const lang=S.lang; S=S0(); S.lang=lang; UI={}; V=null; UNDO=null; closeSheet(); render(); toast(L('Erased','Effacé')); }

/* ---------- menu, about, how to read the screens ---------- */
function menuSheet(){ const opts=[[0,L('midnight','minuit')],[2,L('2 a.m.','2 h')],[4,L('4 a.m.','4 h')],[6,L('6 a.m.','6 h')],[10,L('10 a.m. (nights)','10 h (nuits)')],[14,L('2 p.m. (nights)','14 h (nuits)')]]; if(!opts.some(o=>o[0]===S.roll)) opts.push([S.roll,S.roll+' h']);
  const b=(act,l,cls)=>`<button type="button" data-act="${act}"${cls?` class="${cls}"`:''}>${l}</button>`;
  showSheet(`<h3 id="sheetTitle">Menu</h3><div class="menu">${S.ack?b('hist',L('History','Historique'))+b('list',L('My list','Ma liste'))+b('label',L('Add a food from its label','Ajouter un aliment selon son étiquette'))+b('help',L('How to read the screens','Comment lire les écrans')):''}${b('install',L('Install on this phone','Installer sur ce téléphone'),'inst')}${S.ack?b('backup',L('Back up my data','Sauvegarder mes données')):''}${b('restore',L('Restore from a backup','Restaurer à partir d’une sauvegarde'))}${b('about',L('About and privacy','À propos et confidentialité'))}${S.ack?b('erase',L('Erase everything','Tout effacer'),'danger'):''}</div>
  ${S.ack?`<div class="row" style="margin-top:12px"><label class="small" for="rollSel">${L('My day starts at','Ma journée commence à')}</label><select id="rollSel" class="sel" data-in="roll" style="min-height:44px">${opts.map(([v,l])=>`<option value="${v}" ${S.roll===v?'selected':''}>${l}</option>`).join('')}</select></div>`:''}
  <p class="small muted" style="margin:12px 0 0">v${VER}</p>`); }
const A=(href,txt)=>`<a href="${href}" target="_blank" rel="noopener">${txt}</a>`;
function aboutSheet(){ showSheet(`<h3 id="sheetTitle">${L('About and privacy','À propos et confidentialité')}</h3>
  <p class="small">${L('<b>Made by Tobie and Claude.</b> Free version at ','<b>Créé par Tobie et Claude.</b> Version gratuite à ')}${A('https://v3ktor.org/threshold/','v3ktor.org/threshold')}. © 2026 Tobie David.</p>
  <p class="small">${L('Phase 2 of The Experiment. It’s a log: it counts what you report and shows the counts beside the amounts. It isn’t medical, dietitian or pharmacist advice, and no clinician or dietitian has reviewed it.','Phase 2 de L’Expérience. C’est un journal\u00a0: il compte ce que tu notes et montre les comptes à côté des quantités. Ce n’est pas un avis médical, diététique ou de pharmacien, et aucun clinicien ni diététiste ne l’a examiné.')} ${MINE()}</p>
  <p class="small">${L('Provided as-is, without warranty of any kind. Everything stays in this browser’s storage on this phone. That storage isn’t encrypted, so anyone who can unlock the phone can read it. Nothing is sent anywhere, and nothing is shared with other apps. “Ask AI” only copies text: once you paste it somewhere, it has left your phone.','Fourni tel quel, sans garantie d’aucune sorte. Tout reste dans le stockage de ce navigateur sur ce téléphone. Ce stockage n’est pas chiffré, donc quiconque peut déverrouiller le téléphone peut le lire. Rien n’est envoyé nulle part et rien n’est partagé avec d’autres apps. «\u00a0Demander à l’IA\u00a0» ne fait que copier du texte\u00a0: une fois que tu le colles quelque part, il a quitté ton téléphone.')}</p>
  <p class="small">${L('Free software under the ','Logiciel libre sous la ')}${A('https://github.com/tobiedavid/v3ktor.org/blob/main/LICENSE',L('GNU Affero General Public License','licence publique générale GNU Affero'))}${L(', version 3 or later. Source code: ',', version 3 ou ultérieure. Code source\u00a0: ')}${A('https://github.com/tobiedavid/v3ktor.org','github.com/tobiedavid/v3ktor.org')}</p>
  <p class="small">${L('Food values: Canadian Nutrient File, Health Canada, 2015, licensed under the ','Valeurs nutritives\u00a0: Fichier canadien sur les éléments nutritifs, Santé Canada, 2015, sous la ')}${A('https://open.canada.ca/en/open-government-licence-canada',L('Open Government Licence – Canada','Licence du gouvernement ouvert – Canada'))}${L('; blanks filled from the USDA’s SR28, in the public domain.','; les blancs sont comblés à partir du SR28 de l’USDA, du domaine public.')}</p>
  <p class="small">${L('Histamine estimates: the average for each food type in Table 10 of the European Food Safety Authority’s Scientific Opinion on risk based control of biogenic amine formation in fermented foods (EFSA Journal 2011;9(10):2393). They are averages by food type. They don’t measure your food.','Estimations d’histamine\u00a0: la moyenne de chaque type d’aliment au tableau 10 de l’avis scientifique de l’Autorité européenne de sécurité des aliments sur la formation d’amines biogènes dans les aliments fermentés (EFSA Journal 2011;9(10):2393). Ce sont des moyennes par type d’aliment. Elles ne mesurent pas ton aliment.')}</p>
  <p class="small">${REFLINE()} ${L('The USDA and the European Food Safety Authority have no connection with this app either.','L’USDA et l’Autorité européenne de sécurité des aliments n’ont aucun lien avec cette app non plus.')}</p>
  <p class="small">${L('Look, food list and reference amounts from The Patch and the Food Trial Log.','Apparence, liste d’aliments et quantités de référence tirées de La Patch et du Food Trial Log.')}</p><p class="small muted">v${VER}</p>`); }
function helpSheet(){ const H2=(en,fr,ten,tfr)=>`<p class="small"><b>${L(en,fr)}</b> ${L(ten,tfr)}</p>`;
  showSheet(`<h3 id="sheetTitle">${L('How to read the screens','Comment lire les écrans')}</h3>`
  +H2('What the app does.','Ce que fait l’app.','You report meals and effects. The app counts them and sets the counts beside the amounts you ate. It doesn’t say what they mean.','Tu notes des repas et des effets. L’app les compte et met les comptes à côté des quantités que tu as mangées. Elle ne dit pas ce qu’ils veulent dire.')
  +H2('A complete day.','Une journée complète.','A day counts once it has a meal and either an effect or a tap on “No effects today”. A day left open stays out of the Threshold rows, so a day you didn’t report on is never read as a day with nothing.','Une journée compte dès qu’elle a un repas et soit un effet, soit un appui sur «\u00a0Aucun effet aujourd’hui\u00a0». Une journée laissée ouverte reste hors des lignes de l’onglet Seuil\u00a0: une journée que tu n’as pas notée n’est jamais lue comme une journée sans rien.')
  +H2('Home.','L’accueil.','Today’s meals and effects, in order. Tap a meal for what it held. Tap an effect for the meals reported in the hours before it: the hours are the ones set on the slider in Threshold. Poor sleep is counted with the day before, so it opens that day’s meals. Earlier days are in Menu → History.','Les repas et les effets d’aujourd’hui, dans l’ordre. Appuie sur un repas pour voir ce qu’il contenait. Appuie sur un effet pour voir les repas notés dans les heures d’avant : ces heures sont celles réglées sur le curseur de l’onglet Seuil. Un mauvais sommeil est compté avec la journée d’avant, alors il ouvre les repas de cette journée-là. Les journées d’avant sont dans Menu → Historique.')
  +H2('The ring.','L’anneau.','Under Nutrition. What you reported eating in the period, by weight, as a day on average: fat, protein, complex carbs, lactose, other sugars and fibre. The key under it has the grams, and the middle has their total. Alcohol, caffeine and the other compounds are in the card below it, as totals for the period. “Carbs, kind not listed” are the carbs of foods whose sugars Health Canada doesn’t list.','Dans l’onglet Nutrition. Ce que tu as noté avoir mangé pendant la période, selon le poids, pour une journée en moyenne\u00a0: gras, protéines, glucides complexes, lactose, autres sucres et fibres. La légende en dessous donne les grammes, et le milieu donne leur total. L’alcool, la caféine et les autres composés sont dans la carte en dessous, en totaux pour la période. Les «\u00a0glucides, sorte non indiquée\u00a0» sont les glucides des aliments dont Santé Canada n’indique pas les sucres.')
  +H2('Histamine, estimated.','Histamine, estimée.','One of the other compounds. It’s the weight of each serving times the average for its food type in a 2011 European table. The amount in your own piece can be many times more or less: one kind of cheese has measured from under 5 to over 1,000 mg per kg. Read it as a count of histamine food.','Un des autres composés. C’est le poids de chaque portion multiplié par la moyenne de son type d’aliment dans un tableau européen de 2011. La quantité dans ton propre morceau peut être plusieurs fois plus grande ou plus petite\u00a0: une même sorte de fromage a déjà mesuré de moins de 5 à plus de 1\u00a0000 mg par kg. Lis-le comme un compte d’aliments à histamine.')
  +H2('Other compounds.','Autres composés.','What your food carried beyond the ring, in six families: amines, plant compounds, fermentable sugars, added, other, and minerals. Grams or milligrams where a source gives a figure, marked ≈ when it is an estimate. Portions where it doesn’t. Tap a name for what it is, how the body clears it and where the figure comes from. A food added from its label carries what you tick on its form.','Ce que tes aliments contenaient en plus de l’anneau, en six familles : amines, composés végétaux, sucres fermentescibles, ajoutés, autres, et minéraux. En grammes ou en milligrammes quand une source donne un chiffre, avec ≈ quand c’est une estimation. En portions sinon. Appuie sur un nom pour savoir ce que c’est, comment le corps l’élimine et d’où vient le chiffre. Un aliment ajouté selon son étiquette contient ce que tu coches dans son formulaire.')
  +H2('The Threshold rows.','Les lignes de Seuil.','Each row is one thing you ate or drank. A thing you never had has no row. Each meal or day is a dot on it: the further right, the more it had. Filled dots are the meals or days the effect was reported for. Empty dots are all the others. The more meals you report, the more accurate it gets. Nothing is averaged. The kinds of fat and of sugar sit under their own row, each with its own mark: saturated, monounsaturated and polyunsaturated fat under fat; fructose, glucose, sucrose, maltose, galactose and lactose under sugars.','Chaque ligne est une chose que tu as mangée ou bue. Une chose que tu n’as jamais prise n’a pas de ligne. Chaque repas ou journée y est un point : plus il est à droite, plus il en contenait. Les points pleins sont les repas ou les journées pour lesquels l’effet a été noté. Les points vides sont tous les autres. Plus tu notes de repas, plus c’est précis. Aucune moyenne n’est faite. Les sortes de gras et de sucres sont sous leur propre ligne, chacune avec sa marque : les gras saturés, monoinsaturés et polyinsaturés sous le gras; le fructose, le glucose, le sucrose, le maltose, le galactose et le lactose sous les sucres.')
  +H2('The mark.','La marque.','A mark stands at the amount that best puts the filled dots on one side of it and the empty dots on the other, and the sentence under the row counts them. The filled dots can be the ones from the mark up, or the ones under it, when an effect comes with less of a thing. The rows where the mark does that best come first. A row has no mark when no amount does better than none, and those rows come last. Under a row in grams or milligrams, the mark is also read in your own foods: about how many servings of each come to it.','Une marque se place à la quantité qui met le mieux les points pleins d’un côté et les points vides de l’autre, et la phrase sous la ligne les compte. Les points pleins peuvent être ceux à partir de la marque, ou ceux en dessous, quand un effet vient avec moins d’une chose. Les lignes où la marque y arrive le mieux viennent en premier. Une ligne n’a pas de marque quand aucune quantité ne sépare ses points, et ces lignes viennent en dernier. Sous une ligne en grammes ou en milligrammes, la marque est aussi lue dans tes propres aliments : environ combien de portions de chacun y arrivent.')
  +H2('Filter.','Filtre.','Pick an effect, or leave it on “Any effect”. Pick several and choose how they combine: all of them together, or any of them. Your picks are kept.','Choisis un effet, ou reste sur « Tout effet ». Choisis-en plusieurs et décide comment ils se combinent : tous ensemble, ou n’importe lequel. Tes choix sont gardés.')
  +H2('Settings.','Réglages.','Choose the reading. “After a meal” reads one meal and the hours after it: the slider sets how many, from 1 to 8, and it starts at 4. An effect picked alone keeps its own hours. One effect can fall in the hours after two meals, and then it counts for both. “Over a day” reads the total for a day with that day, that night and the next day. Poor sleep counts for the night before the morning you report it. “Rows shown” sets how many rows you see: Minimal keeps only the rows with a clear mark, where more than half of the filled dots are on one side and more than half of the empty dots on the other; Medium keeps every row with a mark; Full shows them all.','Choisis la lecture. « Après un repas » lit un repas et les heures suivantes : le curseur règle combien, de 1 à 8, et il commence à 4. Un effet choisi seul garde ses propres heures. Un même effet peut tomber dans les heures qui suivent deux repas, et il compte alors pour les deux. « Sur une journée » lit le total d’une journée avec ce jour-là, cette nuit-là et le lendemain. Un mauvais sommeil compte pour la nuit qui précède le matin où tu le notes. « Lignes affichées » règle combien de lignes tu vois : Minimale garde seulement les lignes à la marque nette, où plus de la moitié des points pleins sont d’un côté et plus de la moitié des points vides de l’autre; Moyenne garde toutes les lignes qui ont une marque; Complète les montre toutes.')
  +H2('When a meal or a day is counted.','Quand une journée ou un repas est compté.','A meal joins the rows as soon as an effect is reported after it, or once its hours are over with none. A day joins once the day after it is over, so the next day’s effects are all in. When nothing is reported for the day after, a day joins only if the effect is already there.','Un repas entre dans les lignes dès qu’un effet est noté après, ou quand ses heures sont terminées sans effet. Une journée y entre quand le lendemain est terminé, pour que les effets du lendemain y soient tous. Quand rien n’est noté pour le lendemain, une journée y entre seulement si l’effet y est déjà.')
  +H2('A row, opened.','Une ligne ouverte.','Tap a row’s name for the foods it came from, and for every amount, with how many meals or days sat on each side.','Appuie sur le nom d’une ligne pour voir les aliments qui en contenaient, et chaque quantité, avec le nombre de repas ou de jours de chaque côté.')
  +H2('When nothing is clear.','Quand rien n’est net.','When no row has a clear mark, the tab offers “Ask AI”, set on everything: it copies your whole log, and the question you ask is yours.','Quand aucune ligne n’a de marque nette, l’onglet propose « Demander à l’IA », réglé sur tout : ça copie tout ton journal, et la question que tu poses est la tienne.')
  +H2('Luck.','Le hasard.','The app puts no number on luck. A split between “With” and “Without” can come from luck alone. Luck has more room when there are few entries, when several things are eaten together, and when meals are closer together than the hours set on the slider. It has less room with more entries, with one thing changed at a time, and with meals further apart than the hours set. The same words sit under every opened row.','L’app ne met aucun chiffre sur le hasard. Un écart entre « Avec » et « Sans » peut venir du seul hasard. Le hasard a plus de place quand il y a peu d’entrées, quand plusieurs choses sont mangées ensemble et quand les repas sont plus rapprochés que les heures réglées sur le curseur. Il a moins de place avec plus d’entrées, avec une seule chose changée à la fois et avec des repas plus espacés que les heures réglées. Les mêmes mots se trouvent sous chaque ligne ouverte.')
  +H2('What the rows can’t tell apart.','Ce que les lignes ne peuvent pas départager.','Things eaten together. If your high-fat meals were also your aged-cheese meals, both rows show the same split. Histamine and tyramine sit in the same foods, and so do gluten and fructans, so their rows move together. “Eaten together” counts the meals or days with 3 or more portions of aged or fermented foods, those with alcohol beside one, and those that held 5 compounds or more: alcohol, caffeine, histamine food and each of the other compounds count once. And what you expect can shape what you feel and report.','Les choses mangées ensemble. Si tes repas riches en gras étaient aussi tes repas de fromage vieilli, les deux lignes montrent le même écart. L’histamine et la tyramine sont dans les mêmes aliments, le gluten et les fructanes aussi, alors leurs lignes bougent ensemble. « Mangés ensemble » compte les repas ou les jours avec 3 portions ou plus d’aliments vieillis ou fermentés, ceux avec de l’alcool et un de ces aliments, et ceux qui contenaient 5 composés ou plus : l’alcool, la caféine, les aliments à histamine et chacun des autres composés comptent une fois. Et ce à quoi tu t’attends peut influencer ce que tu ressens et ce que tu notes.')
  +H2('One food.','Un aliment.','On the Threshold tab, look up a food to see what you reported on the days you ate it, by the amount eaten that day, and on the days without it. Both are read over the same span: that day, that night and the next day.','Dans l’onglet Seuil, cherche un aliment pour voir ce que tu as noté les jours où tu en as mangé, selon la quantité mangée ce jour-là, et les jours sans cet aliment. Les deux sont lus sur la même durée : ce jour-là, cette nuit-là et le lendemain.')
  +H2('Drinks.','Les boissons.','A drink is entered like a meal, water included. Water, plain sparkling water and flavoured sparkling water are three separate entries.','Une boisson se note comme un repas, l’eau aussi. L’eau, l’eau pétillante nature et l’eau pétillante aromatisée sont trois entrées distinctes.')
  +H2('Foods with no numbers.','Aliments sans chiffres.','A food typed by name in the Food Trial Log has no amounts, so its meals stay out of the Threshold rows. A food added from its label has amounts and no vitamins or minerals.','Un aliment entré par son nom dans le Food Trial Log n’a pas de quantités, alors ses repas restent hors des lignes de l’onglet Seuil. Un aliment ajouté selon son étiquette a des quantités, mais pas de vitamines ni de minéraux.')
  +`<p class="mine">${MINE()}</p>`); }

/* ---------- install: the same bar, button and steps as the Food Trial Log ---------- */
const SHARE='<svg class="ico" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 15V3"/><path d="M8 7l4-4 4 4"/><path d="M7 11H5v10h14V11h-2"/></svg>';
const pillHTML=()=>`<span>${L('Install Threshold Log on this phone','Installer Threshold Log sur ce téléphone')}</span><button type="button" class="ipy" data-act="install">${L('Install','Installer')}</button><button type="button" class="ipn" data-act="instno" aria-label="${L('No thanks','Non merci')}">✕</button>`;
function installPill(){ if(FRAMED||STANDALONE||document.getElementById('installPill')) return; try{ if(localStorage.getItem(KEY+'.noinst')) return; }catch(e){ return; }
  const b=document.createElement('div'); b.id='installPill'; b.innerHTML=pillHTML(); document.body.appendChild(b); }
function installSheet(){
  const icon=`<li>${L('From now on, open the app from its icon.','À partir de maintenant, ouvre l’app par son icône.')}</li>`,
    iph=`<ol class="inst">${SAFARI?'':`<li>${L('Open this page in <b>Safari</b>.','Ouvre cette page dans <b>Safari</b>.')}</li>`}<li>${L('Tap <b>⋯</b> beside the address bar, then <b>Share</b>. No <b>⋯</b>? Tap the Share button','Appuie sur <b>⋯</b> à côté de la barre d’adresse, puis sur <b>Partager</b>. Pas de <b>⋯</b>? Appuie sur le bouton Partager')} ${SHARE}.</li><li>${L('Scroll down the list and tap <b>Add to Home Screen</b>.','Descends dans la liste et choisis <b>Sur l’écran d’accueil</b>.')}</li><li>${L('Tap <b>Add</b>.','Appuie sur <b>Ajouter</b>.')}</li>${icon}</ol>`,
    and=`<ol class="inst">${CHROME?'':`<li>${L('Open this page in <b>Chrome</b>.','Ouvre cette page dans <b>Chrome</b>.')}</li>`}<li>${L('Tap the <b>⋮</b> menu at the top right.','Appuie sur le menu <b>⋮</b> en haut à droite.')}</li><li>${L('Tap <b>Add to Home screen</b>. On some phones it says <b>Install app</b>.','Appuie sur <b>Ajouter à l’écran d’accueil</b>. Sur certains téléphones, c’est écrit <b>Installer l’application</b>.')}</li><li>${L('Tap <b>Install</b>.','Appuie sur <b>Installer</b>.')}</li>${icon}</ol>`,
    carry=S.ev.length?`<p class="small">${L('You already have entries here. To bring them along, tap <b>Back up my data</b> in the menu. Then tap <b>Restore from a backup</b> in the installed app.','Tu as déjà des entrées ici. Pour les apporter, appuie sur <b>Sauvegarder mes données</b> dans le menu. Ensuite, appuie sur <b>Restaurer à partir d’une sauvegarde</b> dans l’app installée.')}</p>`:'',
    iosNote=`<p class="small">${L('<b>On an iPhone, install before you start.</b> The installed app does not see the entries made in Safari, or the Food Trial Log’s data: that comes in with its backup file, on the Nutrition tab.','<b>Sur un iPhone, installe avant de commencer.</b> L’app installée ne voit pas les entrées faites dans Safari, ni les données du Food Trial Log\u00a0: celles-là arrivent par son fichier de sauvegarde, dans l’onglet Nutrition.')}</p>${carry}<p class="small muted">${L('Why install: in Safari, an iPhone can erase your entries when you have not opened this page for 7 days. The installed app keeps them.','Pourquoi installer\u00a0: dans Safari, un iPhone peut effacer tes entrées quand tu n’as pas ouvert cette page depuis 7 jours. L’app installée les garde.')}</p>`,
    andNote=CHROME||!carry?'':`<p class="small">${L('Chrome does not see the entries made in this browser.','Chrome ne voit pas les entrées faites dans ce navigateur.')}</p>${carry}`;
  showSheet(`<h3 id="sheetTitle">${L('Install on this phone','Installer sur ce téléphone')}</h3><p class="small">${L('The app gets its own icon on your phone and opens without a connection. There is no store and no account.','L’app a sa propre icône sur ton téléphone et s’ouvre sans connexion. Pas de boutique d’applications, pas de compte.')}</p>${IOS?iph+iosNote:ANDROID?and+andNote:`<p><b>iPhone</b></p>${iph}${iosNote}<p><b>Android</b></p>${and}`}`); }
function navBack(){ if(sheet.classList.contains('on')){ closeSheet(); return true; } if(V){ V=V.prev||null; render(); return true; } if(S.tab!=='home'){ S.tab='home'; render(); return true; } return false; }

