function histDay(){ const k=UI.hday||kAdd(today(),-1), m=/^(\d{4})-(\d\d)-(\d\d)$/.exec(k), d=m&&new Date(+m[1],+m[2]-1,+m[3]);
  if(!d||d.getMonth()!==+m[2]-1||k>today()||+m[1]<2000){ toast(L('Pick a day, today or before','Choisis une journée, aujourd’hui ou avant')); return null; } return k; }
const pnum=v=>{ v=String(v==null?'':v).trim().replace(',','.'); if(v==='') return null; const x=Number(v); return isFinite(x)&&x>=0&&x<10000?Math.round(x*100)/100:NaN; };
