/* the day can turn over while the app sits open on a screen: that screen is drawn again before a tap is taken for the wrong day */
let DAYNOW=today();
function fresh(){ const d=today(); if(d===DAYNOW) return false; DAYNOW=d; if(sheet.classList.contains('on')||V||!S.ack) return false; render(true); return true; }
setInterval(fresh,60000);
document.addEventListener('click',e=>{ const b=e.target.closest('[data-act]'); if(!b||b.disabled) return; const f=ACT[b.dataset.act]; if(!f) return; e.preventDefault();
  if(fresh()){ toast(L('A new day has started. Tap again.','Une nouvelle journée a commencé. Appuie encore.')); return; } f(b,e); });
document.addEventListener('input',e=>{ const el=e.target, k=el.dataset&&el.dataset.in; if(!k) return; const v=el.value;
  if(k==='mq'){ if(!V||V.v!=='meal') return; V.q=v; document.getElementById('mRows').innerHTML=mealRows(); const hq=!!v.trim(); for(const id of ['mTabs','mSame']){ const x=document.getElementById(id); if(x) x.hidden=hq; } return; }
  if(k==='tq'){ UI.tq=v; document.getElementById('tqRows').innerHTML=tqRows(); return; }
  /* the slider moves: the lists under it are read again at once. The slider itself is left alone, so a drag is never cut short. It is saved when the thumb is let go. */
  if(k==='twin'){ const h=Math.round(+v), sel=selOf(), one=sel.length===1?sel[0]:null; if(E.WINS.indexOf(h)<0||h===thrH()) return; if(one) S.fxw[one]=h; else S.twin=h;
    el.setAttribute('aria-valuetext',hrsWord(h)); const tx=document.getElementById('tWinTxt'); if(tx) tx.textContent=hrsAfter(h);
    soon(()=>{ const t0=performance.now(), tmp=document.createElement('div'); tmp.innerHTML=vThr();
      for(const id of ['thrCard','thrBar']){ const a=document.getElementById(id), b=tmp.querySelector('#'+id); if(a&&b) a.innerHTML=b.innerHTML; } thrMs=performance.now()-t0; }); return; }
  if(k==='hday'){ UI.hday=v; return; } if(k==='mat'){ if(V) V.at=v; return; } if(k==='fxat'){ UI.fx.at=v; return; } if(k==='fxown'){ UI.fx.own=v; return; } if(k==='enat'){ UI.en.at=v; return; } if(k==='lb'){ UI.lb[el.dataset.k]=v; return; }
  if(k==='concl'){ const key=el.dataset.k, t=v.slice(0,200); if(t.trim()) S.concl[key]=t; else delete S.concl[key]; UI.dirty=true; save(); } });
document.addEventListener('change',e=>{ const el=e.target;
  if(el.id==='impFile'||el.id==='restoreFile'){ const f=el.files&&el.files[0], fn=el.id==='impFile'?impFile:parseBackup; if(!f) return; const r=new FileReader(); r.onload=()=>fn(String(r.result)); r.onerror=()=>toast(L('That file couldn’t be read','Ce fichier n’a pas pu être lu')); r.readAsText(f); return; }
  if(el.dataset&&el.dataset.in==='twin'){ save(); return; }
  if(el.dataset&&el.dataset.in==='roll'){ S.roll=+el.value; render(true); toast(L('Saved','Enregistré')); } });
document.addEventListener('toggle',e=>{ const k=e.target.dataset&&e.target.dataset.tog; if(k) (UI.tog||(UI.tog={}))[k]=e.target.open; },true);
sheetBg.addEventListener('touchmove',e=>e.preventDefault(),{passive:false}); sheetBg.onclick=closeSheet;
document.addEventListener('keydown',e=>{ if(e.key==='Enter'&&e.target.dataset&&e.target.dataset.in==='fxown'){ e.preventDefault(); ACT.fxadd(); return; }
  if(!sheet.classList.contains('on')) return; if(e.key==='Escape'){ e.preventDefault(); closeSheet(); return; }
  if(e.key==='Tab'){ const f=[...sheet.querySelectorAll('a[href],button:not([disabled]),input:not([tabindex="-1"]),select,textarea,summary')].filter(x=>x.offsetParent!==null); if(!f.length) return; const a=f[0], z=f[f.length-1]; if(e.shiftKey&&(document.activeElement===a||document.activeElement===sheet)){ e.preventDefault(); z.focus(); } else if(!e.shiftKey&&document.activeElement===z){ e.preventDefault(); a.focus(); } } });
/* coming back to the app: "today" and the 4-hour windows are read again */
document.addEventListener('visibilitychange',()=>{ if(!document.hidden&&!sheet.classList.contains('on')&&!V){ DAYNOW=today(); render(true); } });

if(STORE!=='bad') pullProf();
window.addEventListener('storage',e=>{ if(e.key===NUTRI.SHARE&&STORE!=='bad'&&pullProf()) render(true); });
render();
