try{ history.pushState({tl:1},''); window.addEventListener('popstate',()=>{ if(navBack()){ try{ history.pushState({tl:1},''); }catch(e){} } else history.back(); }); }catch(e){}
{ let sx=0, sy=0, st=0;
  document.addEventListener('touchstart',e=>{ const t=e.touches[0]; sx=t.clientX; sy=t.clientY; st=e.touches.length===1&&!(e.target.closest&&e.target.closest('input,select,textarea,.gtabs,.stepsrow,.sheet'))?Date.now():0; },{passive:true});
  document.addEventListener('touchend',e=>{ if(!st) return; const t=e.changedTouches[0], dx=t.clientX-sx, dy=t.clientY-sy; if(Date.now()-st<600&&Math.abs(dx)>90&&Math.abs(dy)<50) navBack(); st=0; },{passive:true}); }
